    vi: 'Hãy kể cho chúng tôi về website bạn muốn. Càng chi tiết, khởi đầu càng thuận lợi. Điều gì chưa chắc thì cứ để trống, chúng ta sẽ cùng làm rõ trong lúc trò chuyện.',
