  artifacts_intro_body: {
    en: 'biveit writes these from what you tell it in the chat, and keeps them up to date as you go. Your site gets built from them, so it\'s worth a quick look.',
    vi: 'biveit soạn các tài liệu này dựa trên những gì bạn chia sẻ trong khung chat và cập nhật liên tục. Website sẽ được xây dựng theo đúng kế hoạch này, nên bạn hãy xem qua nhé.',
    zh: '这些文档由 biveit 根据你在聊天中说的内容撰写，并会随时更新。网站会按照它们来搭建，值得花点时间看看。',
    ja: 'これらはチャットでの内容をもとに biveit が作成し、随時更新しています。サイトはこの設計書どおりに作られるので、一度目を通してみてください。',
    ru: 'biveit составляет эти документы по вашим ответам в чате и обновляет их по ходу дела. Сайт будет собран по ним, так что стоит их просмотреть.',
    ko: 'biveit가 채팅 내용을 바탕으로 작성하고 계속 업데이트해요. 사이트는 이 기획서대로 만들어지니 한번 훑어보세요.',
  },
