  privacy_policy_rights_body: {
    en: '• You can see and change your name, picture and language on your profile page at any time.\n• You can turn analytics on or off at any time from the Cookie Policy page.\n• You can ask us for a copy of your personal information, to correct it, or to delete your account, by emailing {{email}}. We\'ll reply within 30 days.',
    vi: '• Bạn có thể xem và thay đổi tên, ảnh và ngôn ngữ trên trang hồ sơ của mình bất cứ lúc nào.\n• Bạn có thể bật hoặc tắt phân tích bất cứ lúc nào từ trang Chính sách cookie.\n• Bạn có thể yêu cầu chúng tôi gửi bản sao thông tin cá nhân của bạn, sửa thông tin, hoặc xóa tài khoản bằng cách gửi email tới {{email}}. Chúng tôi sẽ phản hồi trong vòng 30 ngày.',
    zh: '• 你可以随时在个人资料页面查看和修改你的姓名、头像和语言。\n• 你可以随时在 Cookie 政策页面开启或关闭分析。\n• 如需获取你的个人信息副本、更正信息或删除账户，请发送邮件至 {{email}}。我们会在 30 天内回复。',
    ja: '• プロフィールページで、お名前、画像、言語をいつでも確認・変更できます。\n• 分析のオン・オフは、Cookie ポリシーのページからいつでも切り替えられます。\n• 個人情報のコピーの請求、訂正、アカウントの削除は、{{email}} までメールでご依頼ください。30 日以内にご返信します。',
    ru: '• Вы можете в любой момент посмотреть и изменить своё имя, фото и язык на странице профиля.\n• Вы можете в любой момент включить или выключить аналитику на странице Политики cookie.\n• Чтобы получить копию своих личных данных, исправить их или удалить аккаунт, напишите нам на {{email}}. Мы ответим в течение 30 дней.',
    ko: '• 프로필 페이지에서 이름, 사진, 언어를 언제든 확인하고 바꿀 수 있습니다.\n• 쿠키 정책 페이지에서 분석을 언제든 켜거나 끌 수 있습니다.\n• 개인정보 사본 요청, 정정, 계정 삭제는 {{email}}로 이메일을 보내 주세요. 30일 이내에 답변드리겠습니다.',
  },
