  privacy_policy_children_body: {
    en: 'biveit is meant for people running a business and isn\'t intended for children under 16. We don\'t knowingly collect information from children. If you believe a child has given us their information, contact us and we\'ll delete it.',
    vi: 'biveit dành cho những người đang kinh doanh và không dành cho trẻ em dưới 16 tuổi. Chúng tôi không cố ý thu thập thông tin từ trẻ em. Nếu bạn cho rằng một đứa trẻ đã cung cấp thông tin cho chúng tôi, hãy liên hệ và chúng tôi sẽ xóa thông tin đó.',
    zh: 'biveit 面向经营业务的人士，不适用于 16 岁以下的儿童。我们不会有意收集儿童的信息。如果你认为有儿童向我们提供了信息，请联系我们，我们会将其删除。',
    ja: 'biveit はビジネスを営む方向けのサービスで、16 歳未満のお子様を対象としていません。お子様の情報を意図的に収集することはありません。お子様が情報を提供したと思われる場合はご連絡ください。削除いたします。',
    ru: 'biveit предназначен для тех, кто ведёт бизнес, и не рассчитан на детей младше 16 лет. Мы сознательно не собираем данные детей. Если вы считаете, что ребёнок передал нам свои данные, свяжитесь с нами, и мы их удалим.',
    ko: 'biveit는 사업을 운영하는 분들을 위한 서비스로, 16세 미만 아동을 대상으로 하지 않습니다. 아동의 정보를 고의로 수집하지 않습니다. 아동이 정보를 제공했다고 생각되면 연락해 주세요. 삭제하겠습니다.',
  },
